import { forwardRef, useState, useCallback, useMemo, useEffect } from "react";
import * as RadixSlider from "@radix-ui/react-slider";
import { clsx } from "clsx";
import { useTheme } from "@theme";

import { SliderProps, SliderAriaLabel } from "./slider.types";
import { SliderClasses, StyledSlider } from "./slider.styles";

const defaultGetItemAriaLabel = (label: SliderAriaLabel): string | undefined => {
  switch (label) {
    case SliderAriaLabel.Thumb:
      return "Value";
    case SliderAriaLabel.ThumbMin:
      return "Minimum value";
    case SliderAriaLabel.ThumbMax:
      return "Maximum value";
  }
};

const Slider = forwardRef<HTMLDivElement, SliderProps>(
  (
    {
      className,
      variant = "default",
      behavior = "single",
      rangeMin = 0,
      rangeMax = 100,
      step = 1,
      defaultValue,
      defaultMinValue,
      defaultMaxValue,
      disabled = false,
      dir,
      value,
      onValueChange,
      getItemAriaLabel = defaultGetItemAriaLabel,
      ...props
    },
    ref,
  ) => {
    const theme = useTheme();
    const rootClasses = clsx(SliderClasses.root, className);

    const initialRange = useMemo(() => {
      if (behavior === "range") {
        return [Number(defaultMinValue ?? rangeMin), Number(defaultMaxValue ?? rangeMax)];
      }
      return [Number(defaultValue ?? rangeMin)];
    }, [behavior, defaultMinValue, defaultMaxValue, defaultValue, rangeMin, rangeMax]);

    const isControlled = value !== undefined;
    const [internalValue, setInternalValue] = useState<number[]>(initialRange);

    const currentValue = isControlled ? value : internalValue;

    const handleChange = useCallback(
      (newValue: number[]) => {
        if (!isControlled) {
          setInternalValue(newValue);
        }
        onValueChange?.(newValue);
      },
      [isControlled, onValueChange],
    );

    useEffect(() => {
      if (isControlled && value !== undefined) {
        if (JSON.stringify(value) !== JSON.stringify(internalValue)) {
          setInternalValue(value);
        }
      }
    }, [value, isControlled, internalValue]);

    return (
      <StyledSlider
        className={rootClasses}
        currentTheme={theme}
        variant={variant}
        {...props}
        onChange={undefined} // prevent passing down onChange from react-hook-form (onValueChange should be used instead)
      >
        <div className={SliderClasses.labelContainer}>
          <span className={SliderClasses.labelMin}>
            {behavior === "single" ? rangeMin : currentValue[0]}
          </span>
          <span className={SliderClasses.labelMax}>
            {behavior === "single" ? currentValue[0] : currentValue[1]}
          </span>
        </div>

        <RadixSlider.Root
          ref={ref}
          className={SliderClasses.sliderRoot}
          dir={dir}
          disabled={disabled}
          max={rangeMax}
          min={rangeMin}
          minStepsBetweenThumbs={1}
          step={step}
          value={currentValue}
          onValueChange={handleChange}
        >
          <RadixSlider.Track className={SliderClasses.track}>
            <RadixSlider.Range className={SliderClasses.range} />
          </RadixSlider.Track>

          {currentValue.map((_: number, index: number) => (
            <RadixSlider.Thumb
              key={index}
              aria-label={getItemAriaLabel(
                behavior === "range"
                  ? index === 0
                    ? SliderAriaLabel.ThumbMin
                    : SliderAriaLabel.ThumbMax
                  : SliderAriaLabel.Thumb,
              )}
              className={SliderClasses.thumb}
            />
          ))}
        </RadixSlider.Root>
      </StyledSlider>
    );
  },
);

Slider.displayName = "Slider";

export default Slider;
